// The settings registry as the settings page sees it, generated by
// mado-settings (cargo test -p mado-settings).
import index from "../generated/settings-index.json";

export type Renderer =
  | "toggle"
  | "number"
  | "text"
  | "select"
  | "list"
  | "url"
  | "shortcut"
  | "duration"
  | "folder"
  | "json";

export interface SettingEntry {
  key: string;
  section: string;
  label: string;
  help: string;
  keywords: string;
  renderer: Renderer;
  protected: boolean;
  feature: string | null;
  undoNotice: boolean;
  restart: "none" | "app" | "engine";
  scope: "app" | "profile";
  options: string[] | null;
}

export const entries = index as SettingEntry[];

/** Sections in page order. */
export const sections: string[] = [...new Set(entries.map((e) => e.section))];

/** Settings of a feature that is off are hidden (spec 06 §6). */
export function visible(
  entry: SettingEntry,
  features: Record<string, boolean | undefined>,
): boolean {
  return entry.feature === null || features[entry.feature] === true;
}
